<?php pageStart('My Reports', $user, 'reports'); ?><main class="page"><div class="topbar"><div><h1>My Reports</h1><p>Track, edit, or cancel your submitted reports.</p></div><div class="nav-actions"><a class="button button-primary" href="index.php?page=report">Report lost item</a><a class="button button-outline" href="index.php?page=report&amp;kind=found">Report found item</a></div></div><?php if ($message): ?><div class="alert alert-success"><?= e($message) ?></div><?php endif; ?><?php if ($error): ?><div class="alert alert-error"><?= e($error) ?></div><?php endif; ?><section class="card"><div class="report-list"><?php if (!$items): ?><p class="muted">No reports submitted yet.</p><?php endif; ?><?php foreach ($items as $item): ?><article class="report"><?php if (!empty($item['image_path'])): ?><img class="item-image" src="<?= e($item['image_path']) ?>" alt="<?= e($item['item_name']) ?> image"><?php endif; ?><div><h3><?= e($item['item_name']) ?></h3><p><?= e(ucfirst($item['item_type'])) ?> · <?= e($item['category']) ?> · <?= e($item['location']) ?> · <?= e($item['date_lost']) ?></p><span class="badge badge-<?= e($item['status'] === 'cancelled' ? 'cancelled' : $item['item_type']) ?>"><?= e($item['status'] === 'cancelled' ? 'Cancelled' : ucfirst($item['item_type'])) ?></span></div><div class="nav-actions"><?php if ($item['status'] !== 'cancelled'): ?><a class="button button-outline" href="index.php?page=reports&amp;edit=<?= e($item['id']) ?>">Edit</a><form method="post" action="index.php?page=reports"><input type="hidden" name="action" value="cancel_report"><input type="hidden" name="id" value="<?= e($item['id']) ?>"><button class="button button-secondary" type="submit">Cancel report</button></form><?php endif; ?></div></article><?php endforeach; ?></div></section><?php if ($editItem): ?><section class="card" style="margin-top:20px"><h2>Edit report</h2><form method="post" action="index.php?page=reports" class="form-grid"><input type="hidden" name="action" value="edit_report"><input type="hidden" name="id" value="<?= e($editItem['id']) ?>"><div class="form-field"><label>Item name</label><input class="input" name="item_name" value="<?= e($editItem['item_name']) ?>" required></div><div class="form-field"><label>Category</label><input class="input" name="category" value="<?= e($editItem['category']) ?>" required></div><div class="form-field"><label>Location</label><input class="input" name="location" value="<?= e($editItem['location']) ?>" required></div><div class="form-field"><label>Date</label><input class="input" name="date_lost" type="date" max="<?= e(date('Y-m-d')) ?>" value="<?= e($editItem['date_lost']) ?>" required></div><div class="form-field"><label>Description</label><textarea class="textarea" name="description" required><?= e($editItem['description']) ?></textarea></div><div class="form-field"><label>Identifying details</label><textarea class="textarea" name="identifying_details" required><?= e($editItem['identifying_details']) ?></textarea></div><div class="form-actions"><a class="button button-secondary" href="index.php?page=reports">Cancel</a><button class="button button-primary" type="submit">Save changes</button></div></form></section><?php endif; ?></main><?php pageEnd(); ?>